from typing import Dict, List, Tuple


def verify_coordinate_cocycle(p: int) -> Dict[str, object]:
    """Exhaustively verify the cyclic coordinate cocycle modulo p."""
    if p < 2:
        raise ValueError("p must be at least 2")
    failures: List[Tuple[int, int]] = []
    for g in range(p):
        for h in range(p):
            left = (g + h) % p
            right = (g + h) % p  # c(g) + g·c(h), with trivial action
            if left != right:
                failures.append((g, h))
    coordinate = tuple(range(p))
    coboundaries = {
        tuple((v - v) % p for _g in range(p))
        for v in range(p)
    }
    return {
        "order_in_field": p % p,
        "cocycle_law_holds": not failures,
        "failures": failures,
        "coordinate_values": coordinate,
        "coboundary_tables": sorted(coboundaries),
        "is_coboundary": coordinate in coboundaries,
    }

